#!/bin/sh
# engine-sizes.t.sh: goal:g1.41 B1 + B4 (DG1 22:12Z; hypothesis:g141-b-engine-grow-and-post-pieces-...): (B1) every size the engine states is the MEASURED size: the pieces map in engine.md (## pieces) and every ### heading of the .geometry/engine*.md equal the byte count of their fenced body, and the map lists every piece, agi-boot, agi-boot.service and matrix included; (B4) the engine-grow.md LIMITS line stops saying 'DG1 to rule' and records the ruling (no ring: cell on engine*.md) and the owner-only alternative.
# sh + awk + grep on a TREE, no git, no network, no root, 0 USD. ROOT=<tree> (or $1) = the tree whose .agi/nodes/.geometry/engine*.md is read as checked out; it runs on any tree. The measure is DG1's: the bytes of the lines of the FIRST fenced body (~~~ ... ~~~) under a ### heading, each line plus its newline (it reproduces A1's 447 / 1477 for agi-boot.service / agi-boot).
# Lanes: b1-measure-* the measure finds the pieces (non-vacuous); b1-headings-* every heading states its measured size; b1-map-* every map row is the measured size, no row names an absent piece, every piece is in the map, the three named pieces are; b5-* the fenced bytes of engine.md: the count finds the fences (non-vacuous), the fences balance, the count is <= 8,192 (RULE: the BYTES of every line strictly between a ~~~ open and its close, each plus its newline, the fence lines themselves excluded, over EVERY block of engine.md; counted with LC_ALL=C awk so a multibyte character is its bytes, not 1 -- the same measure as b1, and the one the owner's kb means); b4-* the LIMITS line: no `DG1 to rule`, the exact ruling text + its pointer, and the pointer RESOLVES to the hypothesis node whose `## DG1 RULING on B4` section names the owner-sign alternative.
# R3b + R1 + R2 (council 3/3, goal:g7.16.1.11.5.1, SM 03:35Z-03:39Z; DG2): the maps are read as a UNION over every engine*.md (engine.md carries engine + engine-root; engine-post, engine-wrap, engine-grow each carry their own `## pieces` map): the b1 rows count the union, b1-every-map-line-is-in-its-pieces-home-file and b1-the-maps-are-found-in-the-files-that-need-one pin the split; r1 = no map purpose over 53 chars (bceafece1d's max); r2 = when engine.md's fenced bytes are over 8,192-512 a tip's net must be <= 0 against its BASE (ENGINE_BASE=<rev> or ENGINE_BASE_FILE=<engine.md>; none = FAIL) unless it ADDS a row to the unfenced `## fence exceptions` section (`goal:<id> +<n> B · council <ts> · eviction goal:<id> · OPEN|repaid by goal:<id>|repaid <sha>`) covering the delta; F5 the 8,192 bar (b5) stays unconditional; F6 the eviction goal must be a live goal node; F7 an exception is debt (a row cannot be repaid while still over the margin, none stays OPEN under it, a second OPEN row needs ` · two-open ruling: <why>`). Run on a tip: ENGINE_BASE=<its base rev> sh engine-sizes.t.sh
# Honest limits: bytes, not meaning; engine.md's FENCED total is asserted (b5, goal:g7.16.1.11.5 ruling R', belam 10-10: the owner's "the bootstrap PACKAGE is under 8kb" = what boots = the fenced bytes; ONE counting rule, stated at b5), its WHOLE total (<= 12,288) is NOT (prose outside a fence is free by that ruling; whole is 9,913 B on 3bbfd7cf15); a heading whose first fence is not its piece body is not a case the lane can know.
R0=${ROOT:-${1:-$(cd "$(dirname "$0")/../../.." && pwd)}};G=$R0/.agi/nodes/.geometry;f=0;T=$(mktemp -d);trap 'rm -rf $T' 0
ok(){ if eval "$2";then echo "ok $1";else echo "FAIL $1";f=$((f+1));fi;}
ls $G/engine*.md >/dev/null 2>&1&&[ -f $G/engine.md ]||{ echo "FAIL inputs: $G/engine*.md";exit 99;}
# heads: "name stated measured" for every ### heading that has a fenced body, across engine*.md
for F in $G/engine*.md;do LC_ALL=C awk '
function emit(){ k=split(FILENAME,pp,"/"); print name, (st==""?"-":st), n, pp[k] }
/^### /{ if(name!=""&&fz==2) emit(); name=$2; st=""; if(match($0,/\([0-9]+ B\)/)) st=substr($0,RSTART+1,RLENGTH-4); fz=0; n=0; next }
/^## /{ if(name!=""&&fz==2) emit(); name=""; fz=0; next }
name!=""{ if(fz==0&&/^~~~/){fz=1;next} if(fz==1){ if(/^~~~/){fz=2;next} n+=length($0)+1 } }
END{ if(name!=""&&fz==2) emit() }' $F;done >$T/heads
# map: "name size file purpose-length" for each row of every ## pieces fence of every engine*.md (R3b, council 03:3xZ: engine.md keeps the maps of engine + engine-root; engine-post, engine-wrap and engine-grow each carry their own). The UNION of the maps is what b1 reads
for F in $G/engine*.md;do LC_ALL=C awk -v fn=${F##*/} '/^## pieces/{m=1;next} /^## /{m=0} m&&/^~~~/{fz=!fz;next} m&&fz&&match($0,/^[^ ]+ +[0-9]+ B +/){split($0,a," ");u=substr($0,RSTART+RLENGTH);print a[1],a[2],fn,length(u)}' $F;done >$T/map
nh=$(wc -l <$T/heads|tr -d ' ');nm=$(wc -l <$T/map|tr -d ' ')
ok "b1-measure-finds-the-pieces the measure found $nh fenced pieces under ### headings (want >= 40) and $nm rows in the ## pieces map (want >= 30)" '[ $nh -ge 40 ]&&[ $nm -ge 30 ]'
stale=$(awk '$2!=$3{printf "%s(%s/%s) ",$1,$2,$3}' $T/heads);ns=$(awk '$2!=$3' $T/heads|wc -l|tr -d ' ')
ok "b1-headings-state-the-measured-size $ns stale heading(s) of $nh (want 0): [${stale% }]" '[ $ns = 0 ]'
off=$(awk 'NR==FNR{m[$1]=$3;next} ($1 in m)&&$2!=m[$1]{printf "%s(%s/%s) ",$1,$2,m[$1]}' $T/heads $T/map);no=$(echo "$off"|wc -w|tr -d ' ')
ok "b1-map-rows-equal-the-measured-size $no map row(s) whose size differs from the measured piece (want 0): [${off% }]" '[ $no = 0 ]'
ghost=$(awk 'NR==FNR{m[$1]=1;next} !($1 in m){printf "%s ",$1}' $T/heads $T/map);ng=$(echo "$ghost"|wc -w|tr -d ' ')
ok "b1-map-names-no-absent-piece $ng map row(s) naming a piece with no ### heading + fenced body (want 0): [${ghost% }]" '[ $ng = 0 ]'
miss=$(awk 'NR==FNR{m[$1]=1;next} !($1 in m){printf "%s ",$1}' $T/map $T/heads);nx=$(echo "$miss"|wc -w|tr -d ' ')
ok "b1-map-lists-every-piece $nx measured piece(s) absent from the map (want 0): [${miss% }]" '[ $nx = 0 ]'
for p in agi-boot agi-boot.service matrix;do ok "b1-map-lists-$p the map has a row for $p: $(awk -v p=$p '$1==p' $T/map|wc -l|tr -d ' ') (want 1)" '[ "$(awk -v p=$p "\$1==p" $T/map|wc -l|tr -d " ")" = 1 ]';done
# RB-2: the map is counted, not just measured row by row: the row count equals the `###` block count, no piece is named twice, and the stated "map of N pieces" in engine.md's title equals both
nblk=$(cat $G/engine*.md|grep -c '^### ');nrow=$nm;ndup=$(awk '{c[$1]++} END{for(k in c)if(c[k]>1)n++; print n+0}' $T/map);dups=$(awk '{c[$1]++} END{for(k in c)if(c[k]>1)printf "%s(x%s) ",k,c[k]}' $T/map)
ntitle=$(grep -m1 -o 'map of [0-9]* pieces' $G/engine.md|grep -o '[0-9]*');nt=$(grep -c 'map of [0-9]* pieces' $G/engine.md)
ok "b1-map-row-count-equals-the-block-count the ## pieces map has $nrow row(s), engine*.md has $nblk ### block(s) (want equal, both >= 40)" '[ "$nrow" = "$nblk" ]&&[ "$nblk" -ge 40 ]'
ok "b1-map-names-no-piece-twice $ndup piece name(s) listed more than once in the map (want 0): [${dups% }]" '[ $ndup = 0 ]'
ok "b1-the-title-number-equals-the-map-and-the-blocks engine.md states 'map of N pieces' $nt time(s) (want 1): N = ${ntitle:-none} (want $nrow = $nblk)" '[ "$nt" = 1 ]&&[ "$ntitle" = "$nrow" ]&&[ "$ntitle" = "$nblk" ]'
# R3b (council 03:3xZ, SM 03:36Z): each engine*.md map lists ITS OWN pieces (engine.md also carries engine-root's: it is the zygote's index); a map line lives in the file that holds the piece's ### block
awk 'NR==FNR{h[$1]=($4=="engine-root.md"?"engine.md":$4);next} ($1 in h)&&$3!=h[$1]{printf "%s(in %s, home %s)\n",$1,$3,h[$1]}' $T/heads $T/map >$T/home;nhm=$(wc -l <$T/home|tr -d ' ');home=$(tr '\n' ' ' <$T/home)
ok "b1-every-map-line-is-in-its-pieces-home-file $nhm map line(s) sit in a file other than the one holding the piece's ### block (want 0; engine-root's pieces are listed in engine.md): [${home% }]" '[ $nhm = 0 ]'
nfm=$(awk '{c[$3]++} END{n=0;for(k in c)n++;print n}' $T/map);mapfiles=$(awk '{c[$3]++} END{for(k in c)printf "%s(%s) ",k,c[k]}' $T/map);nomap=;for F in engine.md engine-post.md engine-wrap.md engine-grow.md;do awk -v f=$F '$3==f{n++} END{exit n>0}' $T/map||continue;nomap="$nomap$F ";done;nnm=$(echo "$nomap"|wc -w|tr -d ' ')
ok "b1-the-maps-are-found-in-the-files-that-need-one the maps found per file: [${mapfiles% }] ($nfm file(s)); files with pieces but NO map: $nnm (want 0) [${nomap% }] (engine.md carries engine + engine-root; engine-post, engine-wrap, engine-grow carry their own)" '[ "$nnm" = 0 ]'
# R1: no map purpose longer than today's max (53 chars on bceafece1d); the purpose = the text after the 'NNNN B' of a map row; bytes, LC_ALL=C (all today's purposes are ASCII)
pmax=$(awk '{if($4>m)m=$4} END{print m+0}' $T/map);pover=$(awk '$4>53{printf "%s(%s) ",$1,$4}' $T/map);npv=$(echo "$pover"|wc -w|tr -d ' ')
ok "r1-no-map-purpose-is-longer-than-53 the longest purpose in the $nm map row(s) is $pmax char(s) (want <= 53), $npv row(s) over: [${pover% }] (non-vacuous: >= 30 rows read)" '[ "$npv" = 0 ]&&[ "$nm" -ge 30 ]'
# B4 (DG1 ruling (a), 13:36Z: the line carries `ruled: no ring cell, g141-b`; the why and the owner-sign alternative live on the hypothesis node's `## DG1 RULING on B4` section): the LIMITS line of engine-grow.md and its pointer. There is NO bare `owner` grep: the line already says 'a broken owner schema', so a word count could never go red when the ruling or its alternative was deleted (the old row was vacuous).
L=$(grep -m1 'LIMITS:' $G/engine-grow.md);dg=$(grep -c 'DG1 to rule' $G/engine-grow.md);ru=$(echo "$L"|grep -cF 'ruled: no ring cell, g141-b');rg=$(echo "$L"|grep -c 'ring:')
ok "b4-the-limits-line-no-longer-asks-DG1-to-rule 'DG1 to rule' appears $dg time(s) in engine-grow.md (want 0)" '[ $dg = 0 ]'
ok "b4-the-limits-line-carries-the-ruling-and-its-pointer the LIMITS line holds the EXACT text 'ruled: no ring cell, g141-b': $ru (want 1) and still says ring: $rg (want 1 line)" '[ "$ru" = 1 ]&&[ "$rg" = 1 ]'
ptr=$(echo "$L"|sed -n 's/.*ruled: no ring cell, \([A-Za-z0-9-]*\).*/\1/p'|head -1);hy=$(ls $R0/.agi/nodes/hypothesis/$ptr-*.md 2>/dev/null);nh=$(echo "$hy"|grep -c .)
hdr=0;os=0;[ "$nh" = 1 ]&&{ hdr=$(grep -c '^## DG1 RULING on B4' "$hy");os=$(awk '/^## DG1 RULING on B4/{s=1;next} /^## |^<!-- THOUGHT:BEGIN/{s=0} s' "$hy"|grep -c 'owner-sign');}
ok "b4-the-pointer-resolves the pointer in the line is [${ptr:-none}]: $nh hypothesis file(s) .agi/nodes/hypothesis/${ptr:-?}-*.md (want 1), its '## DG1 RULING on B4' heading $hdr time(s) (want 1), the section (up to the next ## or the THOUGHT block, which also says owner-sign) names the alternative ('owner-sign') on $os line(s) (want >= 1)" '[ -n "$ptr" ]&&[ "$nh" = 1 ]&&[ "$hdr" = 1 ]&&[ "$os" -ge 1 ]'
# --- b5 (goal:g7.16.1.11.5, ruling R'): the bar is the FENCED bytes of engine.md <= 8,192. ONE counting rule, written here: the bytes of the lines STRICTLY BETWEEN a ~~~ open and its close, each + its newline, fence lines excluded, over every block of engine.md (diagram, loop, pieces map, the files), LC_ALL=C. (DG1 measured 8,099 on 3bbfd7cf15 with a UTF-8 awk, which counts a multibyte character as 1: ten lines inside the fences carry non-ASCII, 92 bytes of difference; SM's 8,191 is this same rule in BYTES, the unit the owner's "8kb" names. Counting the fence lines too, or `sed -n '/^~~~/,/^~~~/p'|wc -c`, gives 8,253: a different rule, NOT used.)
EM=$G/engine.md;nf=$(grep -c '^~~~' $EM);fb=$(LC_ALL=C awk '/^~~~/{f=!f;next} f{n+=length($0)+1} END{print n+0}' $EM);fl=$(LC_ALL=C awk '/^~~~/{f=!f;next} f{n++} END{print n+0}' $EM)
ok "b5-measure-finds-the-fences the count found $nf fence line(s) (want >= 8: an empty or half parse must not pass) and $fb fenced byte(s) in $fl line(s) (want >= 4000; the floors catch an empty parse, they are NOT a target: a simplification may shrink the fences)" '[ "$nf" -ge 8 ]&&[ "$fb" -ge 4000 ]'
ok "b5-the-fences-balance engine.md has $nf ~~~ line(s) (want an even number: every block is closed; an odd count makes the byte count meaningless, so it is a FAIL, never a silent pass)" '[ $((nf%2)) = 0 ]'
ok "b5-the-fenced-bytes-are-within-the-bar engine.md: $fb fenced byte(s) by the rule above (want <= 8192; $((8192-fb)) B left); the whole file is $(wc -c <$EM|tr -d ' ') B (NOT asserted)" '[ "$fb" -le 8192 ]'
# --- R2 (council 03:3xZ, goal:g7.16.1.11.5.1, SM 03:36Z): when engine.md's fenced bytes (the b5 rule) are over 8,192 - 512 = 7,680, a tip that ADDS fenced bytes removes at least as many in the SAME tip (net <= 0), asserted against the tip's own BASE. BASE = ENGINE_BASE=<rev> (read with git -C ROOT show REV:.agi/nodes/.geometry/engine.md) or ENGINE_BASE_FILE=<an engine.md>; with neither, a tip over the margin is a FAIL (a skip is a hole). A NAMED EXCEPTION lives in the graph: an UNFENCED section `## fence exceptions` of engine.md, one row per exception `goal:<id> +<n> B · council <ts> · eviction goal:<id>`; a tip over the margin whose delta vs the base is > 0 passes ONLY if it ADDS such a row (present at the tip, absent at the base) whose +n >= the delta (the largest new row covers it; a row already at the base never does, so a stale row cannot cover a later tip)
MARGIN=$((8192-512));fbase=;bsrc="none";bf=$T/base.md
if [ -n "$ENGINE_BASE_FILE" ];then cp "$ENGINE_BASE_FILE" $bf 2>/dev/null&&bsrc="file";elif [ -n "$ENGINE_BASE" ];then git -C $R0 show "$ENGINE_BASE:.agi/nodes/.geometry/engine.md" >$bf 2>/dev/null&&[ -s $bf ]&&bsrc="rev $ENGINE_BASE";fi
[ "$bsrc" != none ]&&[ -s $bf ]&&fbase=$(LC_ALL=C awk '/^~~~/{f=!f;next} f{n+=length($0)+1} END{print n+0}' $bf)
# exception rows of a file, whole lines, well-formed only: `goal:<id> +<n> B · council <ts> · eviction goal:<id> · OPEN|repaid by goal:<id>|repaid <sha>` (+ ` · two-open ruling: <why>`); the section is UNFENCED. exall = every line of the section that starts with goal: (to count the malformed ones)
exall(){ LC_ALL=C awk '/^~~~/{f=!f;next} f{next} /^## fence exceptions/{s=1;next} /^## /{s=0} s&&/^goal:/{print}' "$1";}
exrows(){ exall "$1"|LC_ALL=C grep -E '^goal:[0-9a-z.]+ \+[0-9]+ B · council [^ ]+ · eviction goal:[0-9a-z.]+ · (OPEN|repaid by goal:[0-9a-z.]+|repaid [0-9a-f]{7,40})( · two-open ruling: .{10,})?$'||:;}
exkey(){ sed 's/ · \(OPEN\|repaid\) .*//;s/ · OPEN$//';}
exrows $EM >$T/ex.tip;exall $EM >$T/ex.alltip;[ -n "$fbase" ]&&exrows $bf >$T/ex.base||: >$T/ex.base
exkey <$T/ex.base|sort >$T/ek.base;exkey <$T/ex.tip|sort >$T/ek.tip
grep -vxFf $T/ek.base $T/ek.tip >$T/ek.new||: ;nnew=$(wc -l <$T/ek.new|tr -d ' ')
newmax=$(sed -n 's/^goal:[0-9a-z.]* +\([0-9]*\) B .*/\1/p' $T/ek.new|sort -n|tail -1);newmax=${newmax:-0}
if [ "$fb" -le "$MARGIN" ];then r2s="under the margin ($fb <= $MARGIN): no eviction owed";r2=0
elif [ -z "$fbase" ];then r2s="OVER the margin ($fb > $MARGIN) and NO BASE given (ENGINE_BASE / ENGINE_BASE_FILE): cannot assert net <= 0";r2=1
elif [ "$fb" -le "$fbase" ];then r2s="over the margin ($fb > $MARGIN) but net $((fb-fbase)) <= 0 against the base ($fbase B, $bsrc)";r2=0
elif [ "$newmax" -ge $((fb-fbase)) ];then r2s="over the margin ($fb > $MARGIN), net +$((fb-fbase)) against the base ($fbase B, $bsrc), covered by a NEW fence-exception row of +$newmax B";r2=0
else r2s="over the margin ($fb > $MARGIN), net +$((fb-fbase)) against the base ($fbase B, $bsrc), $nnew new fence-exception row(s) (largest +$newmax B): NOT covered";r2=1;fi
ok "r2-over-the-margin-a-tip-removes-what-it-adds engine.md fenced bytes: $r2s (want pass; margin $MARGIN B)" '[ $r2 = 0 ]'
# F5-F7 (council 3/3, SM 03:37Z): (F6) every exception's eviction goal RESOLVES to a live goal node; (F7) an exception is DEBT: (a) a row that went OPEN -> repaid in this tip needs the fence back under the margin, (b) no row stays OPEN while the fence is at or under the margin (repaid is owed), (c) a NEW OPEN row while another row is OPEN needs its `two-open ruling` field; (F5) the owner's bar b5 (<= 8,192) is unconditional: an exception never relaxes it (b5 above, no exception input)
nmal=$(( $(wc -l <$T/ex.alltip|tr -d ' ') - $(wc -l <$T/ex.tip|tr -d ' ') ));unres=;for e in $(sed -n 's/.* · eviction goal:\([0-9a-z.]*\) · .*/\1/p' $T/ex.tip);do gf=$R0/.agi/nodes/goal/$e.md;st=$(sed -n 's/^status: *//p' $gf 2>/dev/null|head -1);[ -f "$gf" ]&&[ "$st" != retired ]&&[ "$st" != deprecated ]||unres="$unres$e ";done
ok "r2-exception-rows-are-well-formed-and-their-eviction-goal-resolves $nmal malformed row(s) under '## fence exceptions' (want 0: shape 'goal:<id> +<n> B · council <ts> · eviction goal:<id> · OPEN|repaid by goal:<id>|repaid <sha>'), eviction goal(s) that do not resolve to a live .agi/nodes/goal/<id>.md: [${unres% }] (want none)" '[ "$nmal" = 0 ]&&[ -z "$unres" ]'
nopen=$(grep -c ' · OPEN' $T/ex.tip);nopb=$(grep -c ' · OPEN' $T/ex.base)
flip=0;if [ -n "$fbase" ];then for k in $(grep ' · OPEN' $T/ex.base|exkey|tr ' ' '~');do kk=$(echo "$k"|tr '~' ' ');grep -F "$kk · repaid" $T/ex.tip >/dev/null&&flip=$((flip+1));done;fi
badflip=0;[ "$flip" -gt 0 ]&&[ "$fb" -gt "$MARGIN" ]&&badflip=$flip
stale=0;[ "$fb" -le "$MARGIN" ]&&stale=$nopen
nrul=$(grep ' · OPEN' $T/ex.tip|grep -vc 'two-open ruling:'|tr -d ' ')
unruled=0;if [ "$nopen" -ge 2 ];then unruled=$(grep -F ' · OPEN' $T/ex.tip|exkey|grep -vxFf $T/ek.base|wc -l|tr -d ' ');wr=$(grep -F ' · OPEN' $T/ex.tip|grep -c 'two-open ruling:');unruled=$((unruled-wr));[ $unruled -lt 0 ]&&unruled=0;fi
ok "r2-an-exception-is-debt $nopen OPEN row(s) at the tip ($nopb at the base): rows repaid in this tip while the fence is still over the margin: $badflip (want 0); OPEN rows left while the fence is <= $MARGIN: $stale (want 0: repaid is owed); NEW OPEN rows beyond the first without a 'two-open ruling' field: $unruled (want 0)" '[ $badflip = 0 ]&&[ $stale = 0 ]&&[ $unruled = 0 ]'
# --- b7 (council 3/3, 01:41Z, goal:g7.16.1.11.44 FF2): engine-capsule.md is the one piece file with a BAR of its own: its FENCED bytes (the b5 counting rule, written above: the lines STRICTLY BETWEEN a ~~~ open and its close, each + its newline, over every block of the file) are <= 8,192, so the verbs stay small enough to read whole. Non-vacuous: the file is found, its fences balance and it holds >= 4,000 fenced bytes (an empty parse must not pass).
EC=$G/engine-capsule.md;ef=$(LC_ALL=C awk '/^~~~/{n++;next} END{print n+0}' $EC 2>/dev/null);eb=$(LC_ALL=C awk '/^~~~/{f=!f;next} f{n+=length($0)+1} END{print n+0}' $EC 2>/dev/null)
ok "b7-engine-capsule-is-found-and-its-fences-balance engine-capsule.md has $ef ~~~ line(s) (want an even number >= 4) and $eb fenced byte(s) (want >= 4000: an empty or half parse must not pass)" '[ -f $EC ]&&[ $((ef%2)) = 0 ]&&[ "$ef" -ge 4 ]&&[ "$eb" -ge 4000 ]'
ok "b7-engine-capsule-fenced-bytes-are-within-the-bar engine-capsule.md: $eb fenced byte(s) (want <= 8192; $((8192-eb)) B left)" '[ "$eb" -le 8192 ]&&[ "$eb" -ge 4000 ]'
# --- b6: a SENSE, not a bar (council 3/3, SM 05:06Z): the TOTAL bytes across all engine*.md are PRINTED at every run so "small enough to read whole" stays measured; nothing is asserted about the number. The row fails only if the measure itself is empty (non-vacuous: the 5 files are found and the total is > 0)
nef=$(ls $G/engine*.md|wc -l|tr -d ' ');tot=$(cat $G/engine*.md|wc -c|tr -d ' ');per=$(for F in $G/engine*.md;do printf '%s=%s ' ${F##*/} $(wc -c <$F|tr -d ' ');done)
ok "b6-total-bytes-across-all-engine-md-is-printed engine*.md total $tot B over $nef file(s) [${per% }] (a sense, not a bar: nothing asserted about the size; the row fails only if the measure is empty: want >= 5 files and a total > 0)" '[ "$nef" -ge 5 ]&&[ "$tot" -gt 0 ]'
echo "engine-sizes: $f FAIL"
exit $f
